/**
 * Explicit class list for Button.module.css.
 *
 * A generated `Record<string, string>` would widen every lookup to
 * `string | undefined` under `noUncheckedIndexedAccess`. Naming the classes
 * keeps them `string` and turns a typo — or a class removed from the CSS but
 * still referenced here — into a type error.
 *
 * Keep in sync with Button.module.css.
 */
declare const styles: {
  readonly button: string;
  readonly primary: string;
  readonly secondary: string;
  readonly ghost: string;
  readonly sm: string;
  readonly md: string;
  readonly lg: string;
  readonly fullWidth: string;
};

export default styles;
